cd /Users && for file in /Users/*.jpg; do
  filename=$(basename "$file")
  stat_date=$(stat -f "%Sm" "$file")
  year=${stat_date:0:4}
  month=${stat_date:5:2}
  day=${stat_date:8:2}
  hour=${stat_date:11:2}
  min=${stat_date:14:2}
  newname="${year}-${month}-${day}_${hour}${min}.jpg"
  mkdir -p "/Users/${year}/${month}"
  mv "$file" "/Users/${year}/${month}/${newname}"
done

